MAX_TOKENS = 180000


def compact_history(messages, model, store):
    """Summarise the conversation, but leave every dropped span addressable."""
    transcript_path = store.persist(messages)
    summary = model.summarize(messages)
    summary += f"\ndropped spans remain readable at: {transcript_path}"
    return [{"role": "user", "content": summary}] + messages[-2:]


def restore_span(store, transcript_path, span):
    """Tool the agent may call to rehydrate what compaction discarded."""
    return store.read(transcript_path, span)
